import { execFile, spawn } from "node:child_process";
import os from "node:os";
function getChromiumBrowsers() {
    const platform = os.platform();
    if (platform === "darwin") {
        return [
            {
                name: "Google Chrome",
                defaultIds: ["com.google.chrome"],
                binaryPaths: [
                    "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
                ],
            },
            {
                name: "Chromium",
                defaultIds: ["org.chromium.chromium"],
                binaryPaths: ["/Applications/Chromium.app/Contents/MacOS/Chromium"],
            },
            {
                name: "Brave",
                defaultIds: ["com.brave.browser"],
                binaryPaths: [
                    "/Applications/Brave Browser.app/Contents/MacOS/Brave Browser",
                ],
            },
            {
                name: "Microsoft Edge",
                defaultIds: ["com.microsoft.edgemac"],
                binaryPaths: [
                    "/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge",
                ],
            },
        ];
    }
    if (platform === "linux") {
        return [
            {
                name: "Google Chrome",
                defaultIds: ["google-chrome.desktop", "google-chrome-stable.desktop"],
                binaryPaths: ["google-chrome", "google-chrome-stable"],
            },
            {
                name: "Chromium",
                defaultIds: ["chromium-browser.desktop", "chromium.desktop"],
                binaryPaths: ["chromium-browser", "chromium"],
            },
            {
                name: "Brave",
                defaultIds: ["brave-browser.desktop"],
                binaryPaths: ["brave-browser", "brave"],
            },
            {
                name: "Microsoft Edge",
                defaultIds: ["microsoft-edge.desktop", "microsoft-edge-stable.desktop"],
                binaryPaths: ["microsoft-edge", "microsoft-edge-stable"],
            },
        ];
    }
    if (platform === "win32") {
        return [
            {
                name: "Google Chrome",
                defaultIds: ["chromehtml"],
                binaryPaths: [
                    "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe",
                    "C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe",
                ],
            },
            {
                name: "Brave",
                defaultIds: ["bravehtml"],
                binaryPaths: [
                    "C:\\Program Files\\BraveSoftware\\Brave-Browser\\Application\\brave.exe",
                    "C:\\Program Files (x86)\\BraveSoftware\\Brave-Browser\\Application\\brave.exe",
                ],
            },
            {
                name: "Microsoft Edge",
                defaultIds: ["msedgehtm"],
                binaryPaths: [
                    "C:\\Program Files\\Microsoft\\Edge\\Application\\msedge.exe",
                    "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe",
                ],
            },
        ];
    }
    return [];
}
// Spawn without a shell so URLs/paths containing spaces, quotes, or other
// shell metacharacters can't be reinterpreted as command syntax. Detach +
// unref so the child outlives this process and doesn't hold the event loop.
// Returns the child pid (null if the spawn failed before a pid was assigned)
// for launch diagnostics; it must never be killed to close a browser window.
function spawnDetached(command, args) {
    if (process.env.VITEST || process.env.NODE_ENV === "test") {
        throw new Error("spawnDetached called in a test environment without being mocked");
    }
    try {
        const child = spawn(command, [...args], { detached: true, stdio: "ignore" });
        child.on("error", () => { });
        child.unref();
        return child.pid ?? null;
    }
    catch {
        return null;
    }
}
function openOsDefault(url) {
    const platform = os.platform();
    if (platform === "darwin") {
        return spawnDetached("open", [url]);
    }
    if (platform === "win32") {
        return spawnDetached("cmd", ["/c", "start", "", url]);
    }
    return spawnDetached("xdg-open", [url]);
}
export function openBrowser(url) {
    if (process.env.VITEST || process.env.NODE_ENV === "test") {
        throw new Error("openBrowser called in a test environment without being mocked");
    }
    const pid = openOsDefault(url);
    return pid === null
        ? { pid: null, launched: false, method: "none", reason: "launch-failed" }
        : { pid, launched: true, method: "os-default" };
}
// Chromium app windows can refuse window.close(); target only this login's
// route and random marker, never the launcher PID shared with other windows.
export async function closeLoginWindow(signInUrl) {
    if (os.platform() !== "darwin") {
        return;
    }
    let url;
    try {
        url = new URL(signInUrl);
    }
    catch {
        return;
    }
    const marker = url.searchParams.get("loginWindow");
    if (!["http:", "https:"].includes(url.protocol) ||
        url.username !== "" ||
        url.password !== "" ||
        !/^\/plugin\/auth\/[a-z0-9-]+$/.test(url.pathname) ||
        marker === null ||
        !/^[a-f0-9]{32}$/.test(marker)) {
        return;
    }
    const appNames = getChromiumBrowsers().flatMap((browser) => browser.binaryPaths.flatMap((path) => {
        const appName = path.match(/\/([^/]+)\.app\//)?.[1];
        return appName === undefined ? [] : [appName];
    }));
    await Promise.all(appNames.map((appName) => new Promise((resolve) => {
        const script = [
            "on run argv",
            "  set loginPrefix to item 1 of argv",
            '  set loginMarker to "loginWindow=" & (item 2 of argv) & "&"',
            `  if application "${appName}" is running then`,
            `    tell application "${appName}"`,
            "      repeat with w in (every window)",
            "        try",
            "          repeat with t in (every tab of w)",
            '            set tabUrl to (URL of t) & "&"',
            '            if tabUrl starts with loginPrefix and (tabUrl contains ("?" & loginMarker) or tabUrl contains ("&" & loginMarker)) then',
            "              close t",
            "              exit repeat",
            "            end if",
            "          end repeat",
            "        end try",
            "      end repeat",
            "    end tell",
            "  end if",
            "end run",
        ].join("\n");
        try {
            execFile("osascript", ["-e", script, `${url.origin}${url.pathname}?`, marker], { timeout: 4000 }, () => resolve());
        }
        catch {
            resolve();
        }
    })));
}
